const LESSONS = [
  // ───────── Fundamentos ─────────
  { id: "fund-1", m: "fund",
    tema: { es: "¿Qué es la Biblia?", en: "What is the Bible?" },
    idea: { es: "La Biblia es una biblioteca de 66 libros escritos por unas 40 personas durante unos 1,500 años: reyes, pescadores, pastores, un médico. Los cristianos la creemos Palabra de Dios: Dios habló a través de personas reales, en su propio idioma y su propia época, y por medio de ella nos sigue hablando hoy.", en: "The Bible is a library of 66 books written by about 40 people over roughly 1,500 years: kings, fishermen, shepherds, a doctor. Christians believe it is God's Word: God spoke through real people, in their own language and time, and through it He still speaks to us today." },
    dato: { es: "Se divide en Antiguo Testamento (39 libros, antes de Jesús) y Nuevo Testamento (27 libros, desde Jesús).", en: "It has the Old Testament (39 books, before Jesus) and the New Testament (27 books, from Jesus on)." },
    v: { es: "Toda la Escritura es inspirada por Dios, y útil para enseñar, para redargüir, para corregir, para instruir en justicia.", ref: "2 Timoteo 3:16", en: "All Scripture is God-breathed and is useful for teaching, rebuking, correcting and training in righteousness.", ref_en: "2 Timothy 3:16" },
    leer: { es: "Salmo 19:7-11", en: "Psalm 19:7-11" },
    pregunta: { es: "¿Qué esperas que Dios te diga a través de la Biblia en esta etapa de tu vida?", en: "What do you hope God will say to you through the Bible in this season of your life?" } },

  { id: "fund-2", m: "fund",
    tema: { es: "Cómo leer la Biblia", en: "How to read the Bible" },
    idea: { es: "Lee un poco cada día, con calma, idealmente por la mañana y por la noche. Usa el método OIA: Observación (¿qué dice el pasaje?), Interpretación (¿qué me enseña de Dios?) y Aplicación (¿cómo lo vivo hoy?). Empieza siempre con una oración corta: “Señor, háblame”.", en: "Read a little every day, slowly, ideally morning and night. Use the OIA method: Observation (what does the passage say?), Interpretation (what does it teach me about God?) and Application (how do I live it today?). Always start with a short prayer: “Lord, speak to me.”" },
    dato: { es: "Nuestro pastor recomienda empezar por Mateo, el primer libro del Nuevo Testamento, que cuenta la vida de Jesús desde su nacimiento. Después, Marcos, Lucas y Juan.", en: "Our pastor recommends starting with Matthew, the first book of the New Testament, which tells Jesus' life from His birth. Then Mark, Luke and John." },
    v: { es: "Lámpara es a mis pies tu palabra, y lumbrera a mi camino.", ref: "Salmo 119:105", en: "Your word is a lamp for my feet, a light on my path.", ref_en: "Psalm 119:105" },
    leer: { es: "Salmo 1", en: "Psalm 1" },
    pregunta: { es: "La Biblia nos anima a meditar en la Palabra de día y de noche (Salmo 1:2). ¿Qué momento de la mañana y qué momento de la noche vas a separar para leer?", en: "The Bible encourages us to meditate on the Word day and night (Psalm 1:2). What moment in the morning and what moment at night will you set apart to read?" } },

  { id: "fund-3", m: "fund",
    tema: { es: "¿Quién es Dios?", en: "Who is God?" },
    idea: { es: "Hay un solo Dios, que existe como Padre, Hijo (Jesús) y Espíritu Santo: tres Personas, un solo Dios. Es eterno, todopoderoso y santo, pero también cercano: es amor, y nos conoce por nombre.", en: "There is one God, who exists as Father, Son (Jesus) and Holy Spirit: three Persons, one God. He is eternal, all-powerful and holy, yet also close: He is love, and He knows us by name." },
    dato: { es: "La palabra “Trinidad” no aparece en la Biblia, pero la enseñanza sí: por ejemplo, en el bautismo de Jesús están el Padre, el Hijo y el Espíritu a la vez (Mateo 3:16-17).", en: "The word “Trinity” is not in the Bible, but the teaching is: at Jesus' baptism, for example, the Father, the Son and the Spirit are all present (Matthew 3:16-17)." },
    v: { es: "El que no ama, no ha conocido a Dios; porque Dios es amor.", ref: "1 Juan 4:8", en: "Whoever does not love does not know God, because God is love.", ref_en: "1 John 4:8" },
    leer: { es: "1 Juan 4:7-16", en: "1 John 4:7-16" },
    pregunta: { es: "¿Cómo te imaginas a Dios cuando oras? ¿Lo sientes cercano o lejano?", en: "How do you picture God when you pray? Do you feel Him close or far?" } },

  { id: "fund-4", m: "fund",
    tema: { es: "La creación y el problema del pecado", en: "Creation and the problem of sin" },
    idea: { es: "Dios creó todo bueno, y creó al ser humano a su imagen para vivir en amistad con Él. Adán y Eva desconfiaron de Dios y desobedecieron. El pecado rompió nuestra relación con Dios, con los demás y con la creación. El resto de la Biblia cuenta cómo Dios repara esa relación rota.", en: "God made everything good, and He made human beings in His image to live in friendship with Him. Adam and Eve distrusted God and disobeyed. Sin broke our relationship with God, with others and with creation. The rest of the Bible tells how God repairs that broken relationship." },
    dato: { es: "“Génesis” significa “origen” o “principio”. Es el primer libro de la Biblia.", en: "“Genesis” means “origin” or “beginning”. It is the first book of the Bible." },
    v: { es: "Y creó Dios al hombre a su imagen, a imagen de Dios lo creó; varón y hembra los creó.", ref: "Génesis 1:27", en: "So God created mankind in his own image, in the image of God he created them; male and female he created them.", ref_en: "Genesis 1:27" },
    leer: { es: "Génesis 3", en: "Genesis 3" },
    pregunta: { es: "¿Dónde ves hoy señales de esa relación rota? ¿Y dónde ves todavía la bondad con que Dios creó el mundo?", en: "Where do you see signs of that broken relationship today? And where do you still see the goodness with which God made the world?" } },

  { id: "fund-5", m: "fund",
    tema: { es: "La promesa: de Abraham al Mesías", en: "The promise: from Abraham to the Messiah" },
    idea: { es: "Dios escogió a Abraham y le prometió que por medio de su descendencia serían bendecidas todas las familias de la tierra. De él nació el pueblo de Israel: Moisés lo sacó de la esclavitud en Egipto, David fue su gran rey, y los profetas anunciaron a un Mesías que vendría a salvar. Jesús es el cumplimiento de esa promesa.", en: "God chose Abraham and promised that through his descendants all the families of the earth would be blessed. From him came the people of Israel: Moses led them out of slavery in Egypt, David was their great king, and the prophets announced a Messiah who would come to save. Jesus is the fulfillment of that promise." },
    dato: { es: "“Mesías” (hebreo) y “Cristo” (griego) significan lo mismo: “el ungido”, el escogido por Dios.", en: "“Messiah” (Hebrew) and “Christ” (Greek) mean the same thing: “the anointed one”, the one chosen by God." },
    v: { es: "Porque un niño nos es nacido, hijo nos es dado, y el principado sobre su hombro; y se llamará su nombre Admirable, Consejero, Dios Fuerte, Padre Eterno, Príncipe de Paz.", ref: "Isaías 9:6", en: "For to us a child is born, to us a son is given, and the government will be on his shoulders. And he will be called Wonderful Counselor, Mighty God, Everlasting Father, Prince of Peace.", ref_en: "Isaiah 9:6" },
    leer: { es: "Génesis 12:1-3", en: "Genesis 12:1-3" },
    pregunta: { es: "Dios cumplió su promesa siglos después. ¿Qué promesa de Dios te cuesta esperar?", en: "God kept His promise centuries later. Which of God's promises is hard for you to wait for?" } },

  // ───────── La vida de Jesús ─────────
  { id: "vida-1", m: "vida",
    tema: { es: "El mundo de Jesús", en: "The world of Jesus" },
    idea: { es: "Jesús nació hace unos 2,000 años en Israel, que entonces estaba bajo el Imperio romano. El pueblo judío esperaba al Mesías, y muchos imaginaban un rey guerrero que los liberaría de Roma. Jesús creció en Nazaret, un pueblo pequeño de Galilea, hablaba arameo y trabajó como carpintero.", en: "Jesus was born about 2,000 years ago in Israel, then under the Roman Empire. The Jewish people were waiting for the Messiah, and many pictured a warrior king who would free them from Rome. Jesus grew up in Nazareth, a small town in Galilee, spoke Aramaic and worked as a carpenter." },
    dato: { es: "Nuestro calendario cuenta los años desde el nacimiento de Jesús (antes y después de Cristo), aunque el cálculo antiguo tuvo un pequeño error: probablemente nació entre los años 6 y 4 a.C.", en: "Our calendar counts years from Jesus' birth (BC and AD), though the ancient calculation was slightly off: He was probably born between 6 and 4 BC." },
    v: { es: "Y aquel Verbo fue hecho carne, y habitó entre nosotros (y vimos su gloria, gloria como del unigénito del Padre), lleno de gracia y de verdad.", ref: "Juan 1:14", en: "The Word became flesh and made his dwelling among us. We have seen his glory, the glory of the one and only Son, who came from the Father, full of grace and truth.", ref_en: "John 1:14" },
    leer: { es: "Juan 1:1-14", en: "John 1:1-14" },
    pregunta: { es: "Dios eligió venir a un pueblo pequeño y a una familia sencilla. ¿Qué te dice eso de cómo ve Dios a las personas comunes?", en: "God chose to come to a small town and a humble family. What does that tell you about how God sees ordinary people?" } },

  { id: "vida-2", m: "vida",
    tema: { es: "El nacimiento de Jesús", en: "The birth of Jesus" },
    idea: { es: "El ángel Gabriel le anunció a María, una joven de Nazaret, que tendría un hijo por obra del Espíritu Santo. Con José viajó a Belén, la ciudad del rey David, y allí nació Jesús en un lugar humilde, acostado en un pesebre. Los primeros en recibir la noticia fueron unos pastores: gente sencilla.", en: "The angel Gabriel told Mary, a young woman from Nazareth, that she would have a son by the Holy Spirit. With Joseph she traveled to Bethlehem, King David's town, and there Jesus was born in a humble place and laid in a manger. The first to hear the news were shepherds: ordinary people." },
    dato: { es: "“Jesús” (Yeshúa) significa “Dios salva”, y “Emanuel” significa “Dios con nosotros” (Mateo 1:21-23).", en: "“Jesus” (Yeshua) means “God saves”, and “Immanuel” means “God with us” (Matthew 1:21-23)." },
    v: { es: "Que os ha nacido hoy, en la ciudad de David, un Salvador, que es CRISTO el Señor.", ref: "Lucas 2:11", en: "Today in the town of David a Savior has been born to you; he is the Messiah, the Lord.", ref_en: "Luke 2:11" },
    leer: { es: "Lucas 2:1-20", en: "Luke 2:1-20" },
    pregunta: { es: "¿Qué significa para ti que Dios se haya hecho un bebé, frágil y dependiente?", en: "What does it mean to you that God became a baby, fragile and dependent?" } },

  { id: "vida-3", m: "vida",
    tema: { es: "Juan el Bautista y el bautismo de Jesús", en: "John the Baptist and Jesus' baptism" },
    idea: { es: "Juan, pariente de Jesús, preparaba el camino: llamaba al pueblo a arrepentirse y bautizaba en el río Jordán. Cuando Jesús, de unos 30 años, se bautizó, el Espíritu descendió sobre Él como paloma y se oyó la voz del Padre. Así empezó su ministerio público.", en: "John, Jesus' relative, prepared the way: he called the people to repent and baptized in the Jordan River. When Jesus, about 30 years old, was baptized, the Spirit came down on Him like a dove and the Father's voice was heard. That is how His public ministry began." },
    dato: { es: "Jesús comenzó su ministerio cerca de los 30 años (Lucas 3:23), y este duró unos tres años.", en: "Jesus began His ministry at about 30 (Luke 3:23), and it lasted about three years." },
    v: { es: "Y hubo una voz de los cielos, que decía: Este es mi Hijo amado, en quien tengo complacencia.", ref: "Mateo 3:17", en: "And a voice from heaven said, “This is my Son, whom I love; with him I am well pleased.”", ref_en: "Matthew 3:17" },
    leer: { es: "Mateo 3", en: "Matthew 3" },
    pregunta: { es: "Antes de que Jesús hiciera un solo milagro, el Padre ya dijo que lo amaba. ¿Te cuesta creer que Dios te ama antes de que hagas algo?", en: "Before Jesus did a single miracle, the Father already said He loved Him. Is it hard for you to believe God loves you before you do anything?" } },

  { id: "vida-4", m: "vida",
    tema: { es: "Tentado en el desierto", en: "Tempted in the desert" },
    idea: { es: "Después de su bautismo, Jesús ayunó 40 días en el desierto y el diablo lo tentó tres veces: convertir piedras en pan, lanzarse desde el templo y recibir los reinos del mundo a cambio de adorarlo. Jesús respondió cada vez con la Escritura. Fue tentado como nosotros, pero sin pecar.", en: "After His baptism, Jesus fasted 40 days in the desert and the devil tempted Him three times: turn stones into bread, throw Himself from the temple, and receive the kingdoms of the world in exchange for worshiping him. Each time Jesus answered with Scripture. He was tempted as we are, yet without sin." },
    dato: { es: "Las tres respuestas de Jesús son citas de Deuteronomio (8:3, 6:16 y 6:13).", en: "Jesus' three answers are quotes from Deuteronomy (8:3, 6:16 and 6:13)." },
    v: { es: "No sólo de pan vivirá el hombre, sino de toda palabra que sale de la boca de Dios.", ref: "Mateo 4:4", en: "Man shall not live on bread alone, but on every word that comes from the mouth of God.", ref_en: "Matthew 4:4" },
    leer: { es: "Mateo 4:1-11", en: "Matthew 4:1-11" },
    pregunta: { es: "¿En qué área de tu vida eres más tentado? ¿Qué versículo podrías tener a mano para ese momento?", en: "In what area of your life are you most tempted? What verse could you keep at hand for that moment?" } },

  { id: "vida-5", m: "vida",
    tema: { es: "“Sígueme”: los primeros discípulos", en: "“Follow me”: the first disciples" },
    idea: { es: "Jesús empezó a predicar en Galilea. Caminando junto al mar llamó a Simón (Pedro), a Andrés, a Santiago y a Juan, que eran pescadores, y ellos dejaron sus redes y lo siguieron. Jesús no buscó a los más preparados: llamó a gente común y la formó caminando con ella.", en: "Jesus began preaching in Galilee. Walking by the sea, He called Simon (Peter), Andrew, James and John, who were fishermen, and they left their nets and followed Him. Jesus didn't look for the most qualified: He called ordinary people and shaped them by walking with them." },
    dato: { es: "Un “discípulo” es un aprendiz: alguien que vive cerca de su maestro para aprender a ser como él.", en: "A “disciple” is an apprentice: someone who stays close to their teacher to learn to be like them." },
    v: { es: "Y les dijo Jesús: Venid en pos de mí, y haré que seáis pescadores de hombres.", ref: "Marcos 1:17", en: "“Come, follow me,” Jesus said, “and I will send you out to fish for people.”", ref_en: "Mark 1:17" },
    leer: { es: "Marcos 1:14-20", en: "Mark 1:14-20" },
    pregunta: { es: "Si Jesús te dijera hoy “sígueme”, ¿qué “red” te costaría más soltar?", en: "If Jesus said “follow me” to you today, which “net” would be hardest to let go of?" } },

  { id: "vida-6", m: "vida",
    tema: { es: "Los milagros: señales del Reino", en: "The miracles: signs of the Kingdom" },
    idea: { es: "Jesús convirtió el agua en vino, sanó enfermos, dio vista a ciegos, multiplicó panes, calmó la tormenta y resucitó muertos. Sus milagros no eran un espectáculo: eran señales de quién es Él y de cómo es el Reino de Dios, donde el mal, la enfermedad y la muerte no tienen la última palabra.", en: "Jesus turned water into wine, healed the sick, gave sight to the blind, multiplied bread, calmed the storm and raised the dead. His miracles were not a show: they were signs of who He is and of what the Kingdom of God is like, where evil, sickness and death don't have the last word." },
    dato: { es: "Según el Evangelio de Juan, el primer milagro de Jesús fue en una boda en Caná, donde convirtió el agua en vino (Juan 2:1-11).", en: "According to John's Gospel, Jesus' first miracle was at a wedding in Cana, where He turned water into wine (John 2:1-11)." },
    v: { es: "¿Quién es éste, que aun el viento y el mar le obedecen?", ref: "Marcos 4:41", en: "Who is this? Even the wind and the waves obey him!", ref_en: "Mark 4:41" },
    leer: { es: "Marcos 4:35-41", en: "Mark 4:35-41" },
    pregunta: { es: "¿Cuál es la “tormenta” que hoy necesitas entregarle a Jesús?", en: "What “storm” do you need to hand over to Jesus today?" } },

  { id: "vida-7", m: "vida",
    tema: { es: "“¿Quién decís que soy yo?”", en: "“Who do you say I am?”" },
    idea: { es: "Jesús preguntó a sus discípulos quién creían que era, y Pedro respondió: “Tú eres el Cristo”. Días después, en un monte, Pedro, Santiago y Juan vieron a Jesús transfigurado, resplandeciente, junto a Moisés y Elías. Desde entonces Jesús comenzó a anunciar que iría a Jerusalén a morir y a resucitar.", en: "Jesus asked His disciples who they thought He was, and Peter answered: “You are the Christ.” Days later, on a mountain, Peter, James and John saw Jesus transfigured, shining, with Moses and Elijah. From then on Jesus began to announce that He would go to Jerusalem to die and rise again." },
    dato: { es: "Moisés representa la Ley y Elías a los profetas: los dos apuntaban a Jesús.", en: "Moses represents the Law and Elijah the prophets: both pointed to Jesus." },
    v: { es: "Él les dijo: Y vosotros, ¿quién decís que soy yo? Respondiendo Simón Pedro, dijo: Tú eres el Cristo, el Hijo del Dios viviente.", ref: "Mateo 16:15-16", en: "“But what about you?” he asked. “Who do you say I am?” Simon Peter answered, “You are the Messiah, the Son of the living God.”", ref_en: "Matthew 16:15-16" },
    leer: { es: "Mateo 16:13-17:8", en: "Matthew 16:13-17:8" },
    pregunta: { es: "Más allá de lo que otros dicen, ¿quién es Jesús para ti hoy?", en: "Beyond what others say, who is Jesus to you today?" } },

  { id: "vida-8", m: "vida",
    tema: { es: "Jerusalén y la última cena", en: "Jerusalem and the Last Supper" },
    idea: { es: "Jesús entró en Jerusalén montado en un burrito y la gente lo aclamó con ramas de palma (Domingo de Ramos). Esa semana, en la cena de Pascua, lavó los pies de sus discípulos, partió el pan y compartió la copa. Esa noche oró angustiado en Getsemaní, Judas lo traicionó y fue arrestado.", en: "Jesus entered Jerusalem riding a donkey and the crowd welcomed Him with palm branches (Palm Sunday). That week, at the Passover meal, He washed His disciples' feet, broke the bread and shared the cup. That night He prayed in anguish in Gethsemane, Judas betrayed Him and He was arrested." },
    dato: { es: "La Pascua judía recordaba la liberación de Egipto. Jesús le dio un nuevo sentido: Él es el Cordero que nos libera.", en: "The Jewish Passover remembered the freedom from Egypt. Jesus gave it new meaning: He is the Lamb who sets us free." },
    v: { es: "Y tomó el pan y dio gracias, y lo partió y les dio, diciendo: Esto es mi cuerpo, que por vosotros es dado; haced esto en memoria de mí.", ref: "Lucas 22:19", en: "And he took bread, gave thanks and broke it, and gave it to them, saying, “This is my body given for you; do this in remembrance of me.”", ref_en: "Luke 22:19" },
    leer: { es: "Lucas 22:7-46", en: "Luke 22:7-46" },
    pregunta: { es: "Sabiendo que lo iban a traicionar, Jesús lavó los pies de todos. ¿A quién podrías servir esta semana, aunque no lo merezca?", en: "Knowing He would be betrayed, Jesus washed everyone's feet. Whom could you serve this week, even if they don't deserve it?" } },

  { id: "vida-9", m: "vida",
    tema: { es: "La cruz", en: "The cross" },
    idea: { es: "Jesús fue juzgado, azotado y crucificado bajo el gobernador romano Poncio Pilato. En la cruz perdonó a quienes lo mataban y prometió el paraíso a uno de los ladrones. Su muerte no fue un accidente: dio su vida voluntariamente para cargar con nuestros pecados y reconciliarnos con Dios.", en: "Jesus was tried, flogged and crucified under the Roman governor Pontius Pilate. On the cross He forgave those who were killing Him and promised paradise to one of the criminals. His death was no accident: He gave His life willingly to carry our sins and reconcile us to God." },
    dato: { es: "Cuando Jesús murió, el velo del templo que separaba el lugar santísimo se rasgó de arriba abajo (Mateo 27:51): el camino a Dios quedó abierto.", en: "When Jesus died, the temple curtain that closed off the Most Holy Place was torn from top to bottom (Matthew 27:51): the way to God was opened." },
    v: { es: "Mas él herido fue por nuestras rebeliones, molido por nuestros pecados; el castigo de nuestra paz fue sobre él, y por su llaga fuimos nosotros curados.", ref: "Isaías 53:5", en: "But he was pierced for our transgressions, he was crushed for our iniquities; the punishment that brought us peace was on him, and by his wounds we are healed.", ref_en: "Isaiah 53:5" },
    leer: { es: "Lucas 23:26-49", en: "Luke 23:26-49" },
    pregunta: { es: "En la cruz Jesús dijo: “Padre, perdónalos”. ¿Qué sientes al saber que ese perdón también es para ti?", en: "On the cross Jesus said, “Father, forgive them.” How do you feel knowing that forgiveness is for you too?" } },

  { id: "vida-10", m: "vida",
    tema: { es: "¡Resucitó!", en: "He is risen!" },
    idea: { es: "Al tercer día, unas mujeres fueron al sepulcro y lo encontraron vacío: Jesús había resucitado. Durante 40 días se apareció a sus discípulos, comió con ellos y les enseñó. Porque Jesús vive, nuestra historia no termina en el sepulcro: la resurrección es la base de nuestra esperanza.", en: "On the third day, some women went to the tomb and found it empty: Jesus had risen. For 40 days He appeared to His disciples, ate with them and taught them. Because Jesus lives, our story does not end in the tomb: the resurrection is the foundation of our hope." },
    dato: { es: "Las mujeres fueron las primeras testigos de la resurrección, y Pablo cuenta que Jesús se apareció a más de 500 personas a la vez (1 Corintios 15:6).", en: "Women were the first witnesses of the resurrection, and Paul says Jesus appeared to more than 500 people at once (1 Corinthians 15:6)." },
    v: { es: "Le dijo Jesús: Yo soy la resurrección y la vida; el que cree en mí, aunque esté muerto, vivirá.", ref: "Juan 11:25", en: "Jesus said to her, “I am the resurrection and the life. The one who believes in me will live, even though they die.”", ref_en: "John 11:25" },
    leer: { es: "Lucas 24:1-12", en: "Luke 24:1-12" },
    pregunta: { es: "¿Qué cambia en tu día saber que tu esperanza no depende de tus circunstancias?", en: "What changes in your day when you know your hope doesn't depend on your circumstances?" } },

  { id: "vida-11", m: "vida",
    tema: { es: "La ascensión y la Gran Comisión", en: "The ascension and the Great Commission" },
    idea: { es: "Antes de subir al cielo, Jesús envió a sus discípulos a hacer discípulos en todas las naciones, bautizándolos y enseñándoles. Prometió estar con ellos siempre y enviarles el Espíritu Santo. Luego ascendió al cielo, y los ángeles anunciaron que un día volverá.", en: "Before going up to heaven, Jesus sent His disciples to make disciples of all nations, baptizing and teaching them. He promised to be with them always and to send them the Holy Spirit. Then He ascended to heaven, and angels announced that one day He will return." },
    dato: { es: "Jesús ascendió 40 días después de su resurrección (Hechos 1:3), desde el monte de los Olivos.", en: "Jesus ascended 40 days after His resurrection (Acts 1:3), from the Mount of Olives." },
    v: { es: "Enseñándoles que guarden todas las cosas que os he mandado; y he aquí yo estoy con vosotros todos los días, hasta el fin del mundo.", ref: "Mateo 28:20", en: "And teaching them to obey everything I have commanded you. And surely I am with you always, to the very end of the age.", ref_en: "Matthew 28:20" },
    leer: { es: "Mateo 28:16-20", en: "Matthew 28:16-20" },
    pregunta: { es: "¿Con quién podrías compartir esta semana algo de lo que estás aprendiendo de Jesús?", en: "Who could you share something you're learning about Jesus with this week?" } },

  // ───────── Las enseñanzas de Jesús ─────────
  { id: "ense-1", m: "ense",
    tema: { es: "El Reino de Dios", en: "The Kingdom of God" },
    idea: { es: "El mensaje central de Jesús fue: “el Reino de Dios se ha acercado”. El Reino es donde Dios reina, donde se hace su voluntad. Comenzó con Jesús, crece como una pequeña semilla de mostaza y se completará cuando Él vuelva. Para entrar hay que arrepentirse, es decir, cambiar de dirección, y creer.", en: "Jesus' central message was: “the Kingdom of God has come near.” The Kingdom is wherever God reigns and His will is done. It began with Jesus, grows like a tiny mustard seed, and will be complete when He returns. To enter it we must repent, that is, turn around, and believe." },
    dato: { es: "“Arrepentirse” (metanoia en griego) significa cambiar de mentalidad, dar media vuelta.", en: "“Repent” (metanoia in Greek) means to change your mind, to turn around." },
    v: { es: "El tiempo se ha cumplido, y el reino de Dios se ha acercado; arrepentíos, y creed en el evangelio.", ref: "Marcos 1:15", en: "“The time has come,” he said. “The kingdom of God has come near. Repent and believe the good news!”", ref_en: "Mark 1:15" },
    leer: { es: "Mateo 13:31-33, 44-46", en: "Matthew 13:31-33, 44-46" },
    pregunta: { es: "¿Qué área de tu vida necesita que Dios reine en ella?", en: "Which area of your life needs God to reign in it?" } },

  { id: "ense-2", m: "ense",
    tema: { es: "Las bienaventuranzas", en: "The Beatitudes" },
    idea: { es: "El Sermón del Monte (Mateo 5 a 7) es la enseñanza más famosa de Jesús. Empieza llamando dichosos a los pobres en espíritu, a los que lloran, a los mansos, a los que tienen hambre de justicia, a los misericordiosos, a los de corazón limpio, a los que buscan la paz y a los perseguidos. El Reino pone de cabeza los valores del mundo.", en: "The Sermon on the Mount (Matthew 5 to 7) is Jesus' most famous teaching. It begins by calling blessed the poor in spirit, those who mourn, the meek, those who hunger for righteousness, the merciful, the pure in heart, the peacemakers and the persecuted. The Kingdom turns the world's values upside down." },
    dato: { es: "“Bienaventurado” significa profundamente dichoso, bendecido por Dios; no solo “contento”.", en: "“Blessed” means deeply happy, favored by God; not just “cheerful”." },
    v: { es: "Bienaventurados los pobres en espíritu, porque de ellos es el reino de los cielos.", ref: "Mateo 5:3", en: "Blessed are the poor in spirit, for theirs is the kingdom of heaven.", ref_en: "Matthew 5:3" },
    leer: { es: "Mateo 5:1-16", en: "Matthew 5:1-16" },
    pregunta: { es: "¿Cuál de las bienaventuranzas te desafía más hoy, y por qué?", en: "Which of the Beatitudes challenges you most today, and why?" } },

  { id: "ense-3", m: "ense",
    tema: { es: "El Padre Nuestro", en: "The Lord's Prayer" },
    idea: { es: "Jesús enseñó a sus discípulos a orar con el Padre Nuestro. Es un modelo: primero honrar a Dios y pedir que venga su Reino y se haga su voluntad; después pedir lo necesario para el día, perdón (y perdonar), y ayuda frente a la tentación y el mal.", en: "Jesus taught His disciples to pray with the Lord's Prayer. It is a model: first honor God and ask for His Kingdom to come and His will to be done; then ask for what we need today, for forgiveness (and to forgive), and for help against temptation and evil." },
    dato: { es: "Jesús llamaba a Dios “Abba”, una palabra aramea cercana y cariñosa, como “papá” (Marcos 14:36).", en: "Jesus called God “Abba”, a warm Aramaic word, like “dad” (Mark 14:36)." },
    v: { es: "Padre nuestro que estás en los cielos, santificado sea tu nombre. Venga tu reino. Hágase tu voluntad, como en el cielo, así también en la tierra.", ref: "Mateo 6:9-10", en: "Our Father in heaven, hallowed be your name, your kingdom come, your will be done, on earth as it is in heaven.", ref_en: "Matthew 6:9-10" },
    leer: { es: "Mateo 6:5-15", en: "Matthew 6:5-15" },
    pregunta: { es: "Ora hoy el Padre Nuestro despacio, frase por frase. ¿Qué frase te tocó más?", en: "Pray the Lord's Prayer slowly today, phrase by phrase. Which phrase touched you most?" } },

  { id: "ense-4", m: "ense",
    tema: { es: "No os afanéis", en: "Do not worry" },
    idea: { es: "Jesús enseñó a no vivir angustiados por la comida, la ropa o el mañana. Si Dios alimenta a las aves y viste a las flores del campo, cuánto más cuidará de sus hijos. La clave es buscar primero el Reino de Dios y confiar en que Él suplirá lo demás.", en: "Jesus taught us not to live anxious about food, clothes or tomorrow. If God feeds the birds and clothes the flowers of the field, how much more will He care for His children. The key is to seek His Kingdom first and trust Him to provide the rest." },
    dato: { es: "Jesús lo enseñó en el mismo Sermón del Monte, justo después de hablar de no acumular tesoros en la tierra (Mateo 6:19-21).", en: "Jesus taught this in the same Sermon on the Mount, right after speaking about not storing up treasures on earth (Matthew 6:19-21)." },
    v: { es: "Mas buscad primeramente el reino de Dios y su justicia, y todas estas cosas os serán añadidas.", ref: "Mateo 6:33", en: "But seek first his kingdom and his righteousness, and all these things will be given to you as well.", ref_en: "Matthew 6:33" },
    leer: { es: "Mateo 6:25-34", en: "Matthew 6:25-34" },
    pregunta: { es: "¿Qué te preocupa hoy? Escríbelo abajo y entrégaselo a Dios en oración.", en: "What worries you today? Write it below and hand it to God in prayer." } },

  { id: "ense-5", m: "ense",
    tema: { es: "El gran mandamiento", en: "The greatest commandment" },
    idea: { es: "Le preguntaron a Jesús cuál era el mandamiento más importante. Respondió: amar a Dios con todo el corazón, el alma y la mente, y amar al prójimo como a uno mismo. Toda la Ley se resume en amor. A sus discípulos les dio además un mandamiento nuevo: amarse unos a otros como Él los amó.", en: "Jesus was asked which commandment was the most important. He answered: love God with all your heart, soul and mind, and love your neighbor as yourself. The whole Law is summed up in love. He also gave His disciples a new command: love one another as He loved them." },
    dato: { es: "Jesús unió dos versículos del Antiguo Testamento: Deuteronomio 6:5 y Levítico 19:18.", en: "Jesus joined two Old Testament verses: Deuteronomy 6:5 and Leviticus 19:18." },
    v: { es: "Amarás al Señor tu Dios con todo tu corazón, y con toda tu alma, y con toda tu mente… Y el segundo es semejante: Amarás a tu prójimo como a ti mismo.", ref: "Mateo 22:37-39", en: "Love the Lord your God with all your heart and with all your soul and with all your mind… And the second is like it: Love your neighbor as yourself.", ref_en: "Matthew 22:37-39" },
    leer: { es: "Mateo 22:34-40", en: "Matthew 22:34-40" },
    pregunta: { es: "¿Qué te resulta más difícil: amar a Dios con todo, o amar al prójimo como a ti mismo?", en: "What is harder for you: loving God with everything, or loving your neighbor as yourself?" } },

  { id: "ense-6", m: "ense",
    tema: { es: "Las parábolas: el sembrador", en: "The parables: the sower" },
    idea: { es: "Jesús enseñaba con parábolas: historias sencillas de la vida diaria con un mensaje profundo. En la del sembrador, la semilla (la Palabra de Dios) cae en cuatro clases de tierra: el camino, las piedras, los espinos y la buena tierra. La diferencia no está en la semilla, sino en el corazón que la recibe.", en: "Jesus taught in parables: simple stories from daily life with a deep message. In the parable of the sower, the seed (God's Word) falls on four kinds of soil: the path, the rocks, the thorns and the good soil. The difference is not in the seed but in the heart that receives it." },
    dato: { es: "En los Evangelios hay alrededor de 40 parábolas de Jesús.", en: "There are about 40 parables of Jesus in the Gospels." },
    v: { es: "Mas la que cayó en buena tierra, éstos son los que con corazón bueno y recto retienen la palabra oída, y dan fruto con perseverancia.", ref: "Lucas 8:15", en: "But the seed on good soil stands for those with a noble and good heart, who hear the word, retain it, and by persevering produce a crop.", ref_en: "Luke 8:15" },
    leer: { es: "Lucas 8:4-15", en: "Luke 8:4-15" },
    pregunta: { es: "¿Qué “espinos” (preocupaciones, prisas, distracciones) ahogan la Palabra en tu vida?", en: "What “thorns” (worries, hurry, distractions) choke the Word in your life?" } },

  { id: "ense-7", m: "ense",
    tema: { es: "El buen samaritano", en: "The Good Samaritan" },
    idea: { es: "Un experto en la Ley le preguntó a Jesús: “¿Y quién es mi prójimo?”. Jesús contó de un hombre asaltado en el camino: un sacerdote y un levita pasaron de largo, pero un samaritano, de un pueblo despreciado por los judíos, se detuvo, lo curó y pagó por su cuidado. Mi prójimo es quien necesita mi ayuda, sea quien sea.", en: "An expert in the Law asked Jesus, “And who is my neighbor?” Jesus told of a man robbed on the road: a priest and a Levite passed by, but a Samaritan, from a people the Jews despised, stopped, treated his wounds and paid for his care. My neighbor is whoever needs my help, whoever they are." },
    dato: { es: "Judíos y samaritanos llevaban siglos de enemistad: que el héroe fuera un samaritano era un escándalo para quienes escuchaban.", en: "Jews and Samaritans had centuries of hostility: making a Samaritan the hero was shocking to the listeners." },
    v: { es: "Él dijo: El que usó de misericordia con él. Entonces Jesús le dijo: Ve, y haz tú lo mismo.", ref: "Lucas 10:37", en: "The expert in the law replied, “The one who had mercy on him.” Jesus told him, “Go and do likewise.”", ref_en: "Luke 10:37" },
    leer: { es: "Lucas 10:25-37", en: "Luke 10:25-37" },
    pregunta: { es: "¿Quién es “el herido del camino” cerca de ti esta semana?", en: "Who is “the wounded one on the road” near you this week?" } },

  { id: "ense-8", m: "ense",
    tema: { es: "El hijo pródigo", en: "The prodigal son" },
    idea: { es: "Un hijo pidió su herencia, se fue lejos y la malgastó. Arruinado, decidió volver a casa para trabajar como siervo. Pero su padre lo vio de lejos, corrió, lo abrazó y le hizo una fiesta. El hermano mayor se enojó. Con esta historia Jesús muestra el corazón del Padre: siempre espera y recibe al que regresa.", en: "A son asked for his inheritance, went far away and wasted it. Broke, he decided to go home and work as a servant. But his father saw him from far off, ran, embraced him and threw a party. The older brother was angry. With this story Jesus shows the Father's heart: He always waits for and welcomes whoever comes back." },
    dato: { es: "En Lucas 15 hay tres parábolas seguidas sobre lo perdido: la oveja, la moneda y el hijo.", en: "Luke 15 has three parables in a row about the lost: the sheep, the coin and the son." },
    v: { es: "Y cuando aún estaba lejos, lo vio su padre, y fue movido a misericordia, y corrió, y se echó sobre su cuello, y le besó.", ref: "Lucas 15:20", en: "But while he was still a long way off, his father saw him and was filled with compassion for him; he ran to his son, threw his arms around him and kissed him.", ref_en: "Luke 15:20" },
    leer: { es: "Lucas 15:11-32", en: "Luke 15:11-32" },
    pregunta: { es: "¿Te pareces más al hijo menor o al hermano mayor? ¿Por qué?", en: "Are you more like the younger son or the older brother? Why?" } },

  { id: "ense-9", m: "ense",
    tema: { es: "Nacer de nuevo", en: "Born again" },
    idea: { es: "Nicodemo, un líder religioso, visitó a Jesús de noche. Jesús le dijo que para ver el Reino de Dios hay que “nacer de nuevo”, nacer del Espíritu. No se trata de mejorar un poco, sino de recibir de Dios una vida nueva. En esa conversación Jesús dijo el versículo más conocido de la Biblia.", en: "Nicodemus, a religious leader, visited Jesus at night. Jesus told him that to see the Kingdom of God you must be “born again”, born of the Spirit. It's not about improving a little, but about receiving new life from God. In that conversation Jesus spoke the best-known verse in the Bible." },
    dato: { es: "Nicodemo aparece de nuevo al final: ayudó a sepultar a Jesús (Juan 19:39). Su fe creció con el tiempo.", en: "Nicodemus appears again at the end: he helped bury Jesus (John 19:39). His faith grew over time." },
    v: { es: "Porque de tal manera amó Dios al mundo, que ha dado a su Hijo unigénito, para que todo aquel que en él cree, no se pierda, mas tenga vida eterna.", ref: "Juan 3:16", en: "For God so loved the world that he gave his one and only Son, that whoever believes in him shall not perish but have eternal life.", ref_en: "John 3:16" },
    leer: { es: "Juan 3:1-21", en: "John 3:1-21" },
    pregunta: { es: "Lee Juan 3:16 poniendo tu nombre en lugar de “el mundo”. ¿Cómo suena?", en: "Read John 3:16 with your name in place of “the world”. How does it sound?" } },

  { id: "ense-10", m: "ense",
    tema: { es: "Los “Yo soy” de Jesús", en: "Jesus' “I am” sayings" },
    idea: { es: "En el Evangelio de Juan, Jesús se describe con siete “Yo soy”: el pan de vida, la luz del mundo, la puerta, el buen pastor, la resurrección y la vida, el camino, la verdad y la vida, y la vid verdadera. Cada uno revela algo de lo que Él es para nosotros.", en: "In John's Gospel, Jesus describes Himself with seven “I am” sayings: the bread of life, the light of the world, the gate, the good shepherd, the resurrection and the life, the way, the truth and the life, and the true vine. Each one reveals something of what He is for us." },
    dato: { es: "“Yo soy” recuerda el nombre con que Dios se reveló a Moisés en la zarza ardiente: “YO SOY EL QUE SOY” (Éxodo 3:14).", en: "“I am” echoes the name God revealed to Moses at the burning bush: “I AM WHO I AM” (Exodus 3:14)." },
    v: { es: "Jesús le dijo: Yo soy el camino, y la verdad, y la vida; nadie viene al Padre, sino por mí.", ref: "Juan 14:6", en: "Jesus answered, “I am the way and the truth and the life. No one comes to the Father except through me.”", ref_en: "John 14:6" },
    leer: { es: "Juan 10:1-18", en: "John 10:1-18" },
    pregunta: { es: "¿Cuál de los siete “Yo soy” necesitas más hoy: pan, luz, pastor, camino…?", en: "Which of the seven “I am” sayings do you need most today: bread, light, shepherd, way…?" } },

  // ───────── Los apóstoles ─────────
  { id: "apos-1", m: "apos",
    tema: { es: "Los doce", en: "The twelve" },
    idea: { es: "Después de orar toda una noche, Jesús escogió a doce de sus discípulos para que estuvieran con Él y para enviarlos a predicar. Eran muy distintos: pescadores, un cobrador de impuestos, un zelote (nacionalista). Fueron doce, como las doce tribus de Israel: el comienzo de un nuevo pueblo de Dios.", en: "After praying all night, Jesus chose twelve of His disciples to be with Him and to send them out to preach. They were very different: fishermen, a tax collector, a zealot (nationalist). There were twelve, like the twelve tribes of Israel: the start of a new people of God." },
    dato: { es: "Los doce: Simón Pedro, Andrés, Santiago, Juan, Felipe, Bartolomé, Tomás, Mateo, Santiago hijo de Alfeo, Tadeo, Simón el zelote y Judas Iscariote (luego reemplazado por Matías).", en: "The twelve: Simon Peter, Andrew, James, John, Philip, Bartholomew, Thomas, Matthew, James son of Alphaeus, Thaddaeus, Simon the Zealot and Judas Iscariot (later replaced by Matthias)." },
    v: { es: "Y estableció a doce, para que estuviesen con él, y para enviarlos a predicar.", ref: "Marcos 3:14", en: "He appointed twelve that they might be with him and that he might send them out to preach.", ref_en: "Mark 3:14" },
    leer: { es: "Lucas 6:12-16", en: "Luke 6:12-16" },
    pregunta: { es: "Jesús juntó a un cobrador de impuestos con un zelote, que eran enemigos políticos. ¿Con quién te cuesta convivir en la fe?", en: "Jesus put a tax collector together with a zealot, political enemies. Who is it hard for you to get along with in the faith?" } },

  { id: "apos-2", m: "apos",
    tema: { es: "Pedro: caer y levantarse", en: "Peter: falling and getting up" },
    idea: { es: "Pedro era pescador, impulsivo y valiente. Caminó sobre el agua y se hundió; prometió no negar nunca a Jesús y lo negó tres veces. Después de resucitar, Jesús le preguntó tres veces “¿me amas?” y le confió cuidar de su iglesia. Pedro llegó a ser uno de sus grandes líderes. Dios usa gente imperfecta.", en: "Peter was a fisherman, impulsive and brave. He walked on water and sank; he promised never to deny Jesus and denied Him three times. After rising, Jesus asked him three times “do you love me?” and entrusted him with caring for His church. Peter became one of its great leaders. God uses imperfect people." },
    dato: { es: "Jesús le cambió el nombre de Simón a Pedro (Cefas en arameo), que significa “piedra” (Juan 1:42).", en: "Jesus changed his name from Simon to Peter (Cephas in Aramaic), which means “rock” (John 1:42)." },
    v: { es: "Señor, tú lo sabes todo; tú sabes que te amo. Jesús le dijo: Apacienta mis ovejas.", ref: "Juan 21:17", en: "“Lord, you know all things; you know that I love you.” Jesus said, “Feed my sheep.”", ref_en: "John 21:17" },
    leer: { es: "Juan 21:15-19", en: "John 21:15-19" },
    pregunta: { es: "¿En qué te identificas con Pedro, el que se equivoca y se levanta?", en: "How do you relate to Peter, who falls and gets back up?" } },

  { id: "apos-3", m: "apos",
    tema: { es: "Juan: el discípulo amado", en: "John: the beloved disciple" },
    idea: { es: "Juan y su hermano Santiago eran tan impetuosos que Jesús los llamó “hijos del trueno”. Pero Juan fue transformado: estuvo al pie de la cruz, Jesús le encargó cuidar a su madre María, y llegó a ser el apóstol del amor. Escribió el Evangelio de Juan, tres cartas y el Apocalipsis.", en: "John and his brother James were so fiery that Jesus called them “sons of thunder”. But John was transformed: he stood at the foot of the cross, Jesus entrusted his mother Mary to him, and he became the apostle of love. He wrote John's Gospel, three letters and Revelation." },
    dato: { es: "Según la tradición, Juan fue el único de los doce que no murió como mártir: murió anciano, en Éfeso.", en: "According to tradition, John was the only one of the twelve who was not martyred: he died old, in Ephesus." },
    v: { es: "Nosotros le amamos a él, porque él nos amó primero.", ref: "1 Juan 4:19", en: "We love because he first loved us.", ref_en: "1 John 4:19" },
    leer: { es: "Juan 19:25-27", en: "John 19:25-27" },
    pregunta: { es: "Jesús convirtió a un “hijo del trueno” en el apóstol del amor. ¿Qué parte de tu carácter le pides que transforme?", en: "Jesus turned a “son of thunder” into the apostle of love. What part of your character are you asking Him to transform?" } },

  { id: "apos-4", m: "apos",
    tema: { es: "Andrés y Santiago", en: "Andrew and James" },
    idea: { es: "Andrés, hermano de Pedro, había sido discípulo de Juan el Bautista. Cuando conoció a Jesús, lo primero que hizo fue llevarle a su hermano, y en los Evangelios siempre aparece acercando gente a Jesús. Santiago, hermano de Juan, fue del círculo más cercano de Jesús y el primero de los apóstoles en morir por su fe (Hechos 12:2).", en: "Andrew, Peter's brother, had been a disciple of John the Baptist. When he met Jesus, the first thing he did was bring his brother, and in the Gospels he is always bringing people to Jesus. James, John's brother, was in Jesus' closest circle and the first apostle to die for his faith (Acts 12:2)." },
    dato: { es: "Hay dos apóstoles llamados Santiago (el hijo de Zebedeo y el hijo de Alfeo). Otro Santiago, hermano de Jesús, escribió la carta de Santiago.", en: "There are two apostles named James (son of Zebedee and son of Alphaeus). Another James, Jesus' brother, wrote the letter of James." },
    v: { es: "Éste halló primero a su hermano Simón, y le dijo: Hemos hallado al Mesías (que traducido es, el Cristo).", ref: "Juan 1:41", en: "The first thing Andrew did was to find his brother Simon and tell him, “We have found the Messiah” (that is, the Christ).", ref_en: "John 1:41" },
    leer: { es: "Juan 1:35-42", en: "John 1:35-42" },
    pregunta: { es: "Andrés llevó a su hermano a Jesús. ¿A quién de tu familia o amigos podrías acercar a Él?", en: "Andrew brought his brother to Jesus. Which family member or friend could you bring closer to Him?" } },

  { id: "apos-5", m: "apos",
    tema: { es: "Mateo y Tomás", en: "Matthew and Thomas" },
    idea: { es: "Mateo (también llamado Leví) era cobrador de impuestos, visto como traidor por su pueblo. Jesús lo llamó, y Mateo hizo una fiesta para presentarle a sus amigos; después escribió el Evangelio de Mateo. Tomás dudó de la resurrección hasta ver a Jesús, y entonces hizo una de las confesiones de fe más fuertes de la Biblia.", en: "Matthew (also called Levi) was a tax collector, seen as a traitor by his people. Jesus called him, and Matthew threw a party to introduce Jesus to his friends; later he wrote Matthew's Gospel. Thomas doubted the resurrection until he saw Jesus, and then made one of the strongest confessions of faith in the Bible." },
    dato: { es: "La tradición cuenta que Tomás llevó el evangelio hasta la India.", en: "Tradition says Thomas took the gospel as far as India." },
    v: { es: "Entonces Tomás respondió y le dijo: ¡Señor mío, y Dios mío! Jesús le dijo: Porque me has visto, Tomás, creíste; bienaventurados los que no vieron, y creyeron.", ref: "Juan 20:28-29", en: "Thomas said to him, “My Lord and my God!” Then Jesus told him, “Because you have seen me, you have believed; blessed are those who have not seen and yet have believed.”", ref_en: "John 20:28-29" },
    leer: { es: "Juan 20:24-29", en: "John 20:24-29" },
    pregunta: { es: "Jesús no rechazó a Tomás por dudar. ¿Qué pregunta sincera le harías tú hoy?", en: "Jesus didn't reject Thomas for doubting. What honest question would you ask Him today?" } },

  { id: "apos-6", m: "apos",
    tema: { es: "Judas y Matías", en: "Judas and Matthias" },
    idea: { es: "Judas Iscariote era uno de los doce y manejaba el dinero del grupo, pero lo robaba, y entregó a Jesús por 30 monedas de plata. Lleno de remordimiento, su vida terminó trágicamente. Pedro también falló, pero volvió a Jesús y fue restaurado. Después de la ascensión, los apóstoles eligieron a Matías para ocupar el lugar de Judas.", en: "Judas Iscariot was one of the twelve and kept the group's money, but he stole from it, and he handed Jesus over for 30 pieces of silver. Full of remorse, his life ended tragically. Peter also failed, but he came back to Jesus and was restored. After the ascension, the apostles chose Matthias to take Judas' place." },
    dato: { es: "Para reemplazar a Judas buscaron a alguien que hubiera acompañado a Jesús desde su bautismo hasta la resurrección (Hechos 1:21-22).", en: "To replace Judas they looked for someone who had been with Jesus from His baptism to the resurrection (Acts 1:21-22)." },
    v: { es: "Porque la tristeza que es según Dios produce arrepentimiento para salvación, de que no hay que arrepentirse; pero la tristeza del mundo produce muerte.", ref: "2 Corintios 7:10", en: "Godly sorrow brings repentance that leads to salvation and leaves no regret, but worldly sorrow brings death.", ref_en: "2 Corinthians 7:10" },
    leer: { es: "Hechos 1:15-26", en: "Acts 1:15-26" },
    pregunta: { es: "¿Hay algo que estás cargando solo y que necesitas llevarle a Jesús, como hizo Pedro?", en: "Is there something you're carrying alone that you need to bring to Jesus, as Peter did?" } },

  { id: "apos-7", m: "apos",
    tema: { es: "Pablo: de perseguidor a apóstol", en: "Paul: from persecutor to apostle" },
    idea: { es: "Saulo era un fariseo que perseguía a los cristianos, hasta que Jesús resucitado se le apareció en el camino a Damasco. Quedó ciego tres días, se bautizó y empezó a predicar a Jesús con el mismo celo con que antes lo combatía. Con el nombre de Pablo llevó el evangelio a los no judíos.", en: "Saul was a Pharisee who persecuted Christians, until the risen Jesus appeared to him on the road to Damascus. He was blind for three days, was baptized and began preaching Jesus with the same zeal he once used to fight Him. Known as Paul, he took the gospel to the non-Jewish world." },
    dato: { es: "Pablo no fue uno de los doce, pero escribió 13 cartas del Nuevo Testamento, varias de ellas desde la cárcel.", en: "Paul was not one of the twelve, but he wrote 13 New Testament letters, several of them from prison." },
    v: { es: "De modo que si alguno está en Cristo, nueva criatura es; las cosas viejas pasaron; he aquí todas son hechas nuevas.", ref: "2 Corintios 5:17", en: "Therefore, if anyone is in Christ, the new creation has come: The old has gone, the new is here!", ref_en: "2 Corinthians 5:17" },
    leer: { es: "Hechos 9:1-19", en: "Acts 9:1-19" },
    pregunta: { es: "¿Hay alguien que parecía imposible de cambiar y terminó siendo un ejemplo para ti?", en: "Is there someone who seemed impossible to change and ended up being an example for you?" } },

  // ───────── Nace la iglesia ─────────
  { id: "igle-1", m: "igle",
    tema: { es: "Pentecostés", en: "Pentecost" },
    idea: { es: "Diez días después de la ascensión, los discípulos estaban reunidos orando en Jerusalén. De repente vino un estruendo como de viento, aparecieron lenguas como de fuego y todos fueron llenos del Espíritu Santo. Pedro, el mismo que había negado a Jesús, predicó con valentía y ese día nació la iglesia.", en: "Ten days after the ascension, the disciples were gathered in prayer in Jerusalem. Suddenly came a sound like wind, what looked like tongues of fire appeared, and all were filled with the Holy Spirit. Peter, the same man who had denied Jesus, preached boldly, and that day the church was born." },
    dato: { es: "Pentecostés era una fiesta judía 50 días después de la Pascua; por eso había en Jerusalén judíos de muchos países y lenguas.", en: "Pentecost was a Jewish feast 50 days after Passover, which is why Jews from many countries and languages were in Jerusalem." },
    v: { es: "Y fueron todos llenos del Espíritu Santo, y comenzaron a hablar en otras lenguas, según el Espíritu les daba que hablasen.", ref: "Hechos 2:4", en: "All of them were filled with the Holy Spirit and began to speak in other tongues as the Spirit enabled them.", ref_en: "Acts 2:4" },
    leer: { es: "Hechos 2:1-21", en: "Acts 2:1-21" },
    pregunta: { es: "El Espíritu convirtió a un Pedro temeroso en un predicador valiente. ¿Dónde necesitas tú esa valentía?", en: "The Spirit turned a fearful Peter into a bold preacher. Where do you need that courage?" } },

  { id: "igle-2", m: "igle",
    tema: { es: "La primera comunidad", en: "The first community" },
    idea: { es: "Los primeros cristianos se dedicaban a cuatro cosas: la enseñanza de los apóstoles, la comunión unos con otros, el partimiento del pan y la oración. Compartían lo que tenían para que a nadie le faltara, se reunían en el templo y en las casas, y cada día se añadían nuevas personas.", en: "The first Christians devoted themselves to four things: the apostles' teaching, fellowship, the breaking of bread and prayer. They shared what they had so no one was in need, met in the temple and in homes, and every day new people joined them." },
    dato: { es: "El día de Pentecostés se bautizaron unas 3,000 personas (Hechos 2:41).", en: "On the day of Pentecost about 3,000 people were baptized (Acts 2:41)." },
    v: { es: "Y perseveraban en la doctrina de los apóstoles, en la comunión unos con otros, en el partimiento del pan y en las oraciones.", ref: "Hechos 2:42", en: "They devoted themselves to the apostles' teaching and to fellowship, to the breaking of bread and to prayer.", ref_en: "Acts 2:42" },
    leer: { es: "Hechos 2:37-47", en: "Acts 2:37-47" },
    pregunta: { es: "¿Cuál de estas cuatro prácticas te falta más: la enseñanza, la comunidad, la Santa Cena o la oración?", en: "Which of these four practices do you most lack: teaching, community, communion or prayer?" } },

  { id: "igle-3", m: "igle",
    tema: { es: "Esteban y la expansión", en: "Stephen and the spread" },
    idea: { es: "Esteban, uno de los siete hombres elegidos para servir a las viudas, fue el primer mártir cristiano: murió apedreado perdonando a quienes lo mataban, como Jesús. Saulo (Pablo) aprobaba su muerte. La persecución dispersó a los creyentes, y así el evangelio llegó a Samaria y más allá, como Jesús había dicho.", en: "Stephen, one of seven men chosen to serve the widows, was the first Christian martyr: he was stoned to death while forgiving his killers, like Jesus. Saul (Paul) approved of his death. Persecution scattered the believers, and so the gospel reached Samaria and beyond, just as Jesus had said." },
    dato: { es: "Esos siete servidores se consideran los primeros “diáconos” de la iglesia; “diácono” significa “servidor” (Hechos 6).", en: "Those seven servants are seen as the church's first “deacons”; “deacon” means “servant” (Acts 6)." },
    v: { es: "Y puesto de rodillas, clamó a gran voz: Señor, no les tomes en cuenta este pecado.", ref: "Hechos 7:60", en: "Then he fell on his knees and cried out, “Lord, do not hold this sin against them.”", ref_en: "Acts 7:60" },
    leer: { es: "Hechos 7:54-8:4", en: "Acts 7:54-8:4" },
    pregunta: { es: "Dios usó la persecución para extender el evangelio. ¿Has visto a Dios sacar algo bueno de un momento difícil?", en: "God used persecution to spread the gospel. Have you seen God bring something good out of a hard time?" } },

  { id: "igle-4", m: "igle",
    tema: { es: "Los viajes de Pablo y sus cartas", en: "Paul's journeys and letters" },
    idea: { es: "Pablo hizo tres grandes viajes misioneros por lo que hoy es Turquía y Grecia, fundando iglesias. Después fue llevado preso a Roma. A esas iglesias les escribió cartas para animarlas, enseñarles y corregirlas: Romanos, Corintios, Gálatas, Efesios, Filipenses… Hoy esas cartas nos enseñan a nosotros.", en: "Paul made three great missionary journeys through what is now Turkey and Greece, planting churches. Later he was taken as a prisoner to Rome. He wrote letters to those churches to encourage, teach and correct them: Romans, Corinthians, Galatians, Ephesians, Philippians… Today those letters teach us." },
    dato: { es: "Pablo escribió Filipenses, conocida como la carta de la alegría, mientras estaba preso.", en: "Paul wrote Philippians, known as the letter of joy, while he was in prison." },
    v: { es: "Todo lo puedo en Cristo que me fortalece.", ref: "Filipenses 4:13", en: "I can do all this through him who gives me strength.", ref_en: "Philippians 4:13" },
    leer: { es: "Filipenses 4:4-13", en: "Philippians 4:4-13" },
    pregunta: { es: "Pablo estaba en la cárcel y escribió sobre el gozo. ¿Qué te roba la alegría hoy?", en: "Paul was in prison and wrote about joy. What is stealing your joy today?" } },

  // ───────── Vivir la fe ─────────
  { id: "vivir-1", m: "vivir",
    tema: { es: "La salvación por gracia", en: "Salvation by grace" },
    idea: { es: "No ganamos el cielo con buenas obras. Dios nos lo regala por gracia, y lo recibimos por fe, confiando en lo que Jesús hizo en la cruz. Las buenas obras son nuestra respuesta de gratitud, no el pago.", en: "We don't earn heaven by good works. God gives it as a gift of grace, and we receive it by faith, trusting in what Jesus did on the cross. Good works are our thankful response, not the payment." },
    dato: { es: "“Gracia” significa favor que no merecemos.", en: "“Grace” means favor we do not deserve." },
    v: { es: "Porque por gracia sois salvos por medio de la fe; y esto no de vosotros, pues es don de Dios.", ref: "Efesios 2:8", en: "For it is by grace you have been saved, through faith—and this is not from yourselves, it is the gift of God.", ref_en: "Ephesians 2:8" },
    leer: { es: "Efesios 2:1-10", en: "Ephesians 2:1-10" },
    pregunta: { es: "¿Qué te cuesta más: recibir un regalo sin hacer nada, o darlo sin esperar nada?", en: "What is harder for you: receiving a gift without doing anything, or giving without expecting anything back?" } },

  { id: "vivir-2", m: "vivir",
    tema: { es: "La oración", en: "Prayer" },
    idea: { es: "Orar es hablar con Dios como con un Padre. No necesitas palabras perfectas: puedes darle gracias, contarle lo que sientes, pedirle ayuda y también escucharlo en silencio. Jesús mismo buscaba momentos a solas para orar.", en: "Prayer is talking to God as to a Father. You don't need perfect words: you can thank Him, tell Him how you feel, ask for help and also listen in silence. Jesus Himself sought time alone to pray." },
    dato: { es: "Jesús se apartaba a lugares solitarios para orar (Lucas 5:16).", en: "Jesus withdrew to lonely places to pray (Luke 5:16)." },
    v: { es: "Por nada estéis afanosos, sino sean conocidas vuestras peticiones delante de Dios en toda oración y ruego, con acción de gracias.", ref: "Filipenses 4:6", en: "Do not be anxious about anything, but in every situation, by prayer and petition, with thanksgiving, present your requests to God.", ref_en: "Philippians 4:6" },
    leer: { es: "Lucas 11:1-13", en: "Luke 11:1-13" },
    pregunta: { es: "¿Cuándo fue la última vez que le contaste a Dios algo sin pedirle nada?", en: "When was the last time you told God something without asking Him for anything?" } },

  { id: "vivir-3", m: "vivir",
    tema: { es: "El Espíritu Santo", en: "The Holy Spirit" },
    idea: { es: "El Espíritu Santo es Dios presente en nosotros. Nos consuela, nos guía, nos recuerda las palabras de Jesús y nos da dones para servir a otros. Su obra se nota en el carácter: va produciendo en nosotros el “fruto del Espíritu”.", en: "The Holy Spirit is God present within us. He comforts, guides, reminds us of Jesus' words, and gives gifts to serve others. His work shows in our character: He grows in us the “fruit of the Spirit”." },
    dato: { es: "Jesús llamó al Espíritu “Consolador” (Paracleto en griego): el que viene a nuestro lado a ayudarnos (Juan 14:16).", en: "Jesus called the Spirit the “Advocate” or “Comforter” (Paraclete in Greek): the one who comes alongside to help us (John 14:16)." },
    v: { es: "Mas el fruto del Espíritu es amor, gozo, paz, paciencia, benignidad, bondad, fe, mansedumbre, templanza.", ref: "Gálatas 5:22-23", en: "But the fruit of the Spirit is love, joy, peace, forbearance, kindness, goodness, faithfulness, gentleness and self-control.", ref_en: "Galatians 5:22-23" },
    leer: { es: "Juan 14:15-27", en: "John 14:15-27" },
    pregunta: { es: "¿Cuál de esos frutos le hace más falta a tu semana?", en: "Which of those fruits does your week need most?" } },

  { id: "vivir-4", m: "vivir",
    tema: { es: "El amor: la prueba de fuego", en: "Love: the real test" },
    idea: { es: "El amor cristiano no es solo un sentimiento: es una decisión y una acción. Es paciente, amable, perdona y no lleva cuentas del mal. Jesús dijo que la gente reconocería a sus discípulos por el amor que se tienen.", en: "Christian love is not just a feeling: it is a decision and an action. It is patient, kind, forgives and keeps no record of wrongs. Jesus said people would recognize His disciples by their love for one another." },
    dato: { es: "En griego, “ágape” es el amor que da sin esperar nada a cambio.", en: "In Greek, “agape” is the love that gives without expecting anything back." },
    v: { es: "El amor es sufrido, es benigno; el amor no tiene envidia, el amor no es jactancioso, no se envanece.", ref: "1 Corintios 13:4", en: "Love is patient, love is kind. It does not envy, it does not boast, it is not proud.", ref_en: "1 Corinthians 13:4" },
    leer: { es: "1 Corintios 13", en: "1 Corinthians 13" },
    pregunta: { es: "¿A quién te cuesta más amar hoy? ¿Qué pequeño paso podrías dar?", en: "Who is hardest for you to love right now? What small step could you take?" } },

  { id: "vivir-5", m: "vivir",
    tema: { es: "El perdón", en: "Forgiveness" },
    idea: { es: "Dios nos perdonó mucho más de lo que podríamos devolver. Por eso perdonar a otros no es opcional para el cristiano, aunque no siempre sea fácil ni rápido. Perdonar es soltar la deuda y dejar la justicia en manos de Dios.", en: "God forgave us far more than we could ever repay. That is why forgiving others is not optional for a Christian, even when it is neither easy nor quick. To forgive is to release the debt and leave justice in God's hands." },
    dato: { es: "Perdonar no significa aprobar lo que hizo la otra persona, ni necesariamente volver a confiar de inmediato.", en: "Forgiving does not mean approving what the other person did, nor necessarily trusting them again right away." },
    v: { es: "Antes sed benignos unos con otros, misericordiosos, perdonándoos unos a otros, como Dios también os perdonó a vosotros en Cristo.", ref: "Efesios 4:32", en: "Be kind and compassionate to one another, forgiving each other, just as in Christ God forgave you.", ref_en: "Ephesians 4:32" },
    leer: { es: "Mateo 18:21-35", en: "Matthew 18:21-35" },
    pregunta: { es: "¿Hay algo que necesitas perdonar esta semana?", en: "Is there something you need to forgive this week?" } },

  { id: "vivir-6", m: "vivir",
    tema: { es: "La iglesia: el cuerpo de Cristo", en: "The church: the body of Christ" },
    idea: { es: "La iglesia no es un edificio: es la comunidad de personas que siguen a Jesús. Como un cuerpo, cada miembro es distinto y necesario: cada uno tiene un lugar y un don que aportar. La fe no se vive solo.", en: "The church is not a building: it is the community of people who follow Jesus. Like a body, each member is different and needed: each one has a place and a gift to contribute. Faith is not lived alone." },
    dato: { es: "La palabra “iglesia” (ekklesía) significa “asamblea”, “los llamados”.", en: "The word “church” (ekklesia) means “assembly”, “those called out”." },
    v: { es: "No dejando de congregarnos, como algunos tienen por costumbre, sino exhortándonos.", ref: "Hebreos 10:25", en: "Not giving up meeting together, as some are in the habit of doing, but encouraging one another.", ref_en: "Hebrews 10:25" },
    leer: { es: "1 Corintios 12:12-27", en: "1 Corinthians 12:12-27" },
    pregunta: { es: "¿Qué talento tuyo podría servir a otros en tu iglesia?", en: "What talent of yours could serve others in your church?" } },

  { id: "vivir-7", m: "vivir",
    tema: { es: "El bautismo y la Santa Cena", en: "Baptism and the Lord's Supper" },
    idea: { es: "Jesús dejó a su iglesia dos señales visibles. El bautismo muestra que morimos al pecado y resucitamos a una vida nueva con Cristo. La Santa Cena (Comunión) recuerda su cuerpo entregado y su sangre derramada, hasta que Él vuelva.", en: "Jesus left His church two visible signs. Baptism shows that we die to sin and rise to new life with Christ. The Lord's Supper (Communion) remembers His body given and His blood shed, until He comes again." },
    dato: { es: "Jesús mismo fue bautizado por Juan el Bautista en el río Jordán, y fue Él quien instituyó la Santa Cena en la última cena.", en: "Jesus Himself was baptized by John the Baptist in the Jordan River, and He instituted the Lord's Supper at the Last Supper." },
    v: { es: "Porque somos sepultados juntamente con él para muerte por el bautismo, a fin de que como Cristo resucitó de los muertos por la gloria del Padre, así también nosotros andemos en vida nueva.", ref: "Romanos 6:4", en: "We were therefore buried with him through baptism into death in order that, just as Christ was raised from the dead through the glory of the Father, we too may live a new life.", ref_en: "Romans 6:4" },
    leer: { es: "1 Corintios 11:23-26", en: "1 Corinthians 11:23-26" },
    pregunta: { es: "¿Qué significa para ti recordar el sacrificio de Jesús cada vez que participas de la Santa Cena?", en: "What does it mean to you to remember Jesus' sacrifice each time you take communion?" } },

  { id: "vivir-8", m: "vivir",
    tema: { es: "Vivir la fe en la familia", en: "Living faith in the family" },
    idea: { es: "La fe se contagia en casa: en la mesa, en la oración antes de dormir, en cómo tratamos a quienes amamos. Los hijos aprenden más de lo que ven que de lo que escuchan.", en: "Faith is caught at home: at the table, in prayer before bed, in how we treat those we love. Children learn more from what they see than from what they hear." },
    dato: { es: "Deuteronomio 6 pide hablar de la fe con los hijos “estando en tu casa, y andando por el camino”.", en: "Deuteronomy 6 says to talk about faith with your children “when you sit at home and when you walk along the road”." },
    v: { es: "Instruye al niño en su camino, y aun cuando fuere viejo no se apartará de él.", ref: "Proverbios 22:6", en: "Start children off on the way they should go, and even when they are old they will not turn from it.", ref_en: "Proverbs 22:6" },
    leer: { es: "Deuteronomio 6:4-9", en: "Deuteronomy 6:4-9" },
    pregunta: { es: "¿Qué costumbre de fe podrías empezar esta semana en casa?", en: "What faith habit could you start at home this week?" } },

  { id: "vivir-9", m: "vivir",
    tema: { es: "Esperanza: Jesús volverá", en: "Hope: Jesus will return" },
    idea: { es: "Jesús prometió volver. La Biblia termina con la promesa de un cielo nuevo y una tierra nueva, donde Dios vivirá con su pueblo y enjugará toda lágrima. Mientras tanto, vivimos con esperanza y no con miedo, sabiendo que la historia termina bien.", en: "Jesus promised to return. The Bible ends with the promise of a new heaven and a new earth, where God will live with His people and wipe away every tear. Meanwhile, we live with hope, not fear, knowing the story ends well." },
    dato: { es: "La última oración de la Biblia es: “Amén; sí, ven, Señor Jesús” (Apocalipsis 22:20).", en: "The last prayer in the Bible is: “Amen. Come, Lord Jesus” (Revelation 22:20)." },
    v: { es: "Enjugará Dios toda lágrima de los ojos de ellos; y ya no habrá muerte, ni habrá más llanto, ni clamor, ni dolor; porque las primeras cosas pasaron.", ref: "Apocalipsis 21:4", en: "He will wipe every tear from their eyes. There will be no more death or mourning or crying or pain, for the old order of things has passed away.", ref_en: "Revelation 21:4" },
    leer: { es: "Apocalipsis 21:1-7", en: "Revelation 21:1-7" },
    pregunta: { es: "¿Cómo cambiaría tu semana vivir sabiendo que la historia termina bien?", en: "How would your week change if you lived knowing the story ends well?" } },
  // ───────── La familia ─────────,

  { id: "fam-1", m: "fam",
    tema: {"es": "El matrimonio es idea de Dios", "en": "Marriage is God's idea"},
    idea: {"es": "Desde el principio, Dios creó al hombre y a la mujer y los unió. El matrimonio no es solo un contrato: es un pacto entre los esposos delante de Dios, donde los dos llegan a ser uno.", "en": "From the beginning, God created man and woman and joined them. Marriage isn't just a contract: it's a covenant between husband and wife before God, where the two become one."},
    dato: {"es": "Jesús citó Génesis 2:24 cuando le preguntaron por el matrimonio (Mateo 19:4-6).", "en": "Jesus quoted Genesis 2:24 when asked about marriage (Matthew 19:4-6)."},
    v: { es: "Por tanto, dejará el hombre a su padre y a su madre, y se unirá a su mujer, y serán una sola carne.", ref: "Génesis 2:24", en: "That is why a man leaves his father and mother and is united to his wife, and they become one flesh.", ref_en: "Genesis 2:24" },
    leer: { es: "Génesis 2:18-25", en: "Genesis 2:18-25" },
    pregunta: {"es": "¿Qué significa en su casa que ustedes dos sean \"uno\"?", "en": "What does being \"one\" look like in your home?"} },

  { id: "fam-2", m: "fam",
    tema: {"es": "Amor que se entrega", "en": "Love that gives itself"},
    idea: {"es": "La Biblia pide a los esposos amar a sus esposas como Cristo amó a la Iglesia: sirviendo, cuidando y entregándose. Ese es el modelo de amor en el matrimonio.", "en": "The Bible asks husbands to love their wives as Christ loved the Church: serving, caring and giving themselves. That is the model of love in marriage."},
    dato: {"es": "Efesios 5 empieza el tema con: \"Someteos unos a otros en el temor de Dios\" (v. 21). Es un llamado mutuo.", "en": "Ephesians 5 opens the topic with \"Submit to one another out of reverence for Christ\" (v. 21). It's a mutual call."},
    v: { es: "Maridos, amad a vuestras mujeres, así como Cristo amó a la iglesia, y se entregó a sí mismo por ella.", ref: "Efesios 5:25", en: "Husbands, love your wives, just as Christ loved the church and gave himself up for her.", ref_en: "Ephesians 5:25" },
    leer: { es: "Efesios 5:21-33", en: "Ephesians 5:21-33" },
    pregunta: {"es": "¿Qué gesto concreto de servicio puedes hacer hoy por tu esposa o esposo?", "en": "What concrete act of service can you do for your spouse today?"} },

  { id: "fam-3", m: "fam",
    tema: {"es": "Respeto y honra", "en": "Respect and honor"},
    idea: {"es": "El matrimonio crece con respeto: palabras amables, escuchar con atención y honrar al otro delante de los demás. Pedro pide a los esposos vivir con su esposa con comprensión y darle honor.", "en": "Marriage grows with respect: kind words, careful listening, and honoring each other in front of others. Peter asks husbands to live with their wives with understanding and to give them honor."},
    dato: {"es": "Pedro dice que tratar bien al cónyuge tiene que ver hasta con que \"vuestras oraciones no tengan estorbo\".", "en": "Peter says that treating your spouse well even affects your prayers being \"not hindered\"."},
    v: { es: "Vosotros, maridos, igualmente, vivid con ellas sabiamente, dando honor a la mujer como a vaso más frágil, y como a coherederas de la gracia de la vida.", ref: "1 Pedro 3:7", en: "Husbands, in the same way be considerate as you live with your wives, and treat them with respect as heirs with you of the gracious gift of life.", ref_en: "1 Peter 3:7" },
    leer: { es: "1 Pedro 3:1-9", en: "1 Peter 3:1-9" },
    pregunta: {"es": "¿Cómo pueden mostrarse respeto cuando no están de acuerdo?", "en": "How can you show each other respect when you disagree?"} },

  { id: "fam-4", m: "fam",
    tema: {"es": "El cordón de tres dobleces", "en": "The cord of three strands"},
    idea: {"es": "Un matrimonio con Dios en el centro es más fuerte. Orar juntos, leer la Biblia juntos y congregarse juntos une a la pareja cuando vienen las pruebas.", "en": "A marriage with God at the center is stronger. Praying together, reading the Bible together and going to church together unite a couple when trials come."},
    dato: {"es": "Este versículo se lee mucho en bodas: los dos esposos y Dios son las tres cuerdas.", "en": "This verse is often read at weddings: husband, wife and God are the three strands."},
    v: { es: "Y si alguno prevaleciere contra uno, dos le resistirán; y cordón de tres dobleces no se rompe pronto.", ref: "Eclesiastés 4:12", en: "Though one may be overpowered, two can defend themselves. A cord of three strands is not quickly broken.", ref_en: "Ecclesiastes 4:12" },
    leer: { es: "Eclesiastés 4:9-12", en: "Ecclesiastes 4:9-12" },
    pregunta: {"es": "¿Qué momento de la semana pueden separar para orar juntos como pareja?", "en": "What time this week can you set aside to pray together as a couple?"} },

  { id: "fam-5", m: "fam",
    tema: {"es": "Perdonar en casa", "en": "Forgiving at home"},
    idea: {"es": "En toda familia hay heridas y errores. La Biblia nos pide soportarnos con paciencia y perdonar como Dios nos perdonó. No dejar que el enojo dure hasta la noche.", "en": "Every family has hurts and mistakes. The Bible asks us to bear with each other patiently and forgive as God forgave us, and not let anger last until nightfall."},
    dato: {"es": "Efesios 4:26 dice: \"no se ponga el sol sobre vuestro enojo\".", "en": "Ephesians 4:26 says: \"do not let the sun go down while you are still angry\"."},
    v: { es: "Soportándoos unos a otros, y perdonándoos unos a otros si alguno tuviere queja contra otro. De la manera que Cristo os perdonó, así también hacedlo vosotros.", ref: "Colosenses 3:13", en: "Bear with each other and forgive one another if any of you has a grievance against someone. Forgive as the Lord forgave you.", ref_en: "Colossians 3:13" },
    leer: { es: "Colosenses 3:12-17", en: "Colossians 3:12-17" },
    pregunta: {"es": "¿Hay algo en casa que necesita una conversación y un perdón esta semana?", "en": "Is there something at home that needs a conversation and forgiveness this week?"} },

  { id: "fam-6", m: "fam",
    tema: {"es": "El amor de 1 Corintios 13", "en": "The love of 1 Corinthians 13"},
    idea: {"es": "Este pasaje describe cómo es el amor en la práctica: paciente, amable, sin envidia ni orgullo, sin llevar cuentas del mal. Es una buena lista para revisar el amor en casa.", "en": "This passage describes what love looks like in practice: patient, kind, without envy or pride, keeping no record of wrongs. It's a good checklist for love at home."},
    dato: {"es": "Un ejercicio: lean el pasaje cambiando \"el amor\" por su propio nombre y vean dónde les cuesta.", "en": "An exercise: read the passage replacing \"love\" with your own name and see where it's hard."},
    v: { es: "Todo lo sufre, todo lo cree, todo lo espera, todo lo soporta. El amor nunca deja de ser.", ref: "1 Corintios 13:7-8", en: "It always protects, always trusts, always hopes, always perseveres. Love never fails.", ref_en: "1 Corinthians 13:7-8" },
    leer: { es: "1 Corintios 13:1-13", en: "1 Corinthians 13:1-13" },
    pregunta: {"es": "¿Cuál de las cualidades del amor quieres practicar más en tu familia?", "en": "Which quality of love do you want to practice more in your family?"} },

  { id: "fam-7", m: "fam",
    tema: {"es": "Los hijos son un regalo", "en": "Children are a gift"},
    idea: {"es": "La Biblia llama a los hijos herencia y recompensa de Dios. No son una carga: son personas que Dios nos confía para amarlas, cuidarlas y guiarlas.", "en": "The Bible calls children a heritage and a reward from God. They aren't a burden: they're people God entrusts to us to love, care for and guide."},
    dato: {"es": "Jesús recibió a los niños cuando los discípulos querían apartarlos (Marcos 10:14).", "en": "Jesus welcomed children when the disciples wanted to send them away (Mark 10:14)."},
    v: { es: "He aquí, herencia de Jehová son los hijos; cosa de estima el fruto del vientre.", ref: "Salmo 127:3", en: "Children are a heritage from the Lord, offspring a reward from him.", ref_en: "Psalm 127:3" },
    leer: { es: "Salmo 127", en: "Psalm 127" },
    pregunta: {"es": "¿Qué cualidad de tu hija le agradeces hoy a Dios? Díselo a ella.", "en": "What quality of your daughter do you thank God for today? Tell her."} },

  { id: "fam-8", m: "fam",
    tema: {"es": "Enseñar la fe en casa", "en": "Teaching faith at home"},
    idea: {"es": "Dios pide a los padres hablar de su Palabra en la vida diaria: en casa, en el camino, al acostarse y al levantarse. La fe se enseña más con el ejemplo que con discursos.", "en": "God asks parents to talk about His Word in daily life: at home, on the road, when lying down and getting up. Faith is taught more by example than by speeches."},
    dato: {"es": "Este pasaje (Deuteronomio 6) es parte del Shemá, la oración más importante del pueblo judío.", "en": "This passage (Deuteronomy 6) is part of the Shema, the most important prayer of the Jewish people."},
    v: { es: "Y las repetirás a tus hijos, y hablarás de ellas estando en tu casa, y andando por el camino, y al acostarte, y cuando te levantes.", ref: "Deuteronomio 6:7", en: "Impress them on your children. Talk about them when you sit at home and when you walk along the road, when you lie down and when you get up.", ref_en: "Deuteronomy 6:7" },
    leer: { es: "Deuteronomio 6:4-9", en: "Deuteronomy 6:4-9" },
    pregunta: {"es": "¿En qué momento natural del día pueden hablar de Dios en familia?", "en": "At what natural moment of the day can you talk about God as a family?"} },

  { id: "fam-9", m: "fam",
    tema: {"es": "Instrucción a los hijos", "en": "Instruction to children"},
    idea: {"es": "A los hijos, la Biblia les pide obedecer y honrar a sus padres. Es el primer mandamiento que trae una promesa. Honrar es más que obedecer: es tratar a los padres con respeto y gratitud.", "en": "The Bible asks children to obey and honor their parents. It's the first commandment with a promise. Honoring is more than obeying: it's treating parents with respect and gratitude."},
    dato: {"es": "\"Honra a tu padre y a tu madre\" es el quinto de los Diez Mandamientos (Éxodo 20:12).", "en": "\"Honor your father and your mother\" is the fifth of the Ten Commandments (Exodus 20:12)."},
    v: { es: "Hijos, obedeced en el Señor a vuestros padres, porque esto es justo. Honra a tu padre y a tu madre, que es el primer mandamiento con promesa.", ref: "Efesios 6:1-2", en: "Children, obey your parents in the Lord, for this is right. Honor your father and mother, which is the first commandment with a promise.", ref_en: "Ephesians 6:1-2" },
    leer: { es: "Efesios 6:1-3", en: "Ephesians 6:1-3" },
    pregunta: {"es": "Para la hija: ¿cómo puedes honrar hoy a tus papás? Para los padres: ¿cómo pueden hacer fácil esa obediencia?", "en": "For the daughter: how can you honor your parents today? For the parents: how can you make that obedience easier?"} },

  { id: "fam-10", m: "fam",
    tema: {"es": "Instrucción a los padres", "en": "Instruction to parents"},
    idea: {"es": "A los padres, la Biblia les pide no provocar a ira ni desanimar a sus hijos, sino criarlos con disciplina amorosa y enseñanza del Señor. Corregir sin humillar y escuchar antes de reaccionar.", "en": "The Bible asks parents not to exasperate or discourage their children, but to raise them with loving discipline and the Lord's instruction. Correct without humiliating, and listen before reacting."},
    dato: {"es": "Colosenses 3:21 da la razón: \"para que no se desalienten\".", "en": "Colossians 3:21 gives the reason: \"so they will not become discouraged\"."},
    v: { es: "Y vosotros, padres, no provoquéis a ira a vuestros hijos, sino criadlos en disciplina y amonestación del Señor.", ref: "Efesios 6:4", en: "Fathers, do not exasperate your children; instead, bring them up in the training and instruction of the Lord.", ref_en: "Ephesians 6:4" },
    leer: { es: "Efesios 6:4", en: "Ephesians 6:4" },
    pregunta: {"es": "¿Qué necesita tu hija de ti esta semana: más escucha, más tiempo o más ánimo?", "en": "What does your daughter need from you this week: more listening, more time, or more encouragement?"} },

  { id: "fam-11", m: "fam",
    tema: {"es": "Crecer como Jesús", "en": "Growing like Jesus"},
    idea: {"es": "De niño, Jesús creció en cuatro áreas: sabiduría (mente), estatura (cuerpo), gracia para con Dios (espíritu) y con los hombres (relaciones). Es un buen mapa para el crecimiento de los hijos.", "en": "As a boy, Jesus grew in four areas: wisdom (mind), stature (body), favor with God (spirit) and with people (relationships). It's a good map for children's growth."},
    dato: {"es": "Es el único versículo que resume la adolescencia de Jesús, después de que se quedó en el templo a los 12 años.", "en": "It's the only verse summarizing Jesus' teenage years, after He stayed in the temple at age 12."},
    v: { es: "Y Jesús crecía en sabiduría y en estatura, y en gracia para con Dios y los hombres.", ref: "Lucas 2:52", en: "And Jesus grew in wisdom and stature, and in favor with God and man.", ref_en: "Luke 2:52" },
    leer: { es: "Lucas 2:41-52", en: "Luke 2:41-52" },
    pregunta: {"es": "¿En cuál de las cuatro áreas pueden apoyar más a su hija este mes?", "en": "In which of the four areas can you support your daughter most this month?"} },

  { id: "fam-12", m: "fam",
    tema: {"es": "Mi casa servirá a Dios", "en": "My house will serve the Lord"},
    idea: {"es": "Josué tomó una decisión por su familia: servir a Dios. La fe de una casa empieza con una decisión de los padres y se vive cada día en lo pequeño.", "en": "Joshua made a decision for his family: to serve the Lord. A household's faith starts with the parents' decision and is lived out daily in small things."},
    dato: {"es": "Muchas familias ponen este versículo en la entrada de su casa como recordatorio.", "en": "Many families put this verse at the entrance of their home as a reminder."},
    v: { es: "Pero yo y mi casa serviremos a Jehová.", ref: "Josué 24:15", en: "But as for me and my household, we will serve the Lord.", ref_en: "Joshua 24:15" },
    leer: { es: "Josué 24:14-18", en: "Joshua 24:14-18" },
    pregunta: {"es": "¿Qué costumbre familiar quieren empezar para que su casa sirva a Dios?", "en": "What family habit do you want to start so your home serves the Lord?"} }
];
